"""Minimal standard-library client for OpenAI's Responses API.

The client keeps requests in memory only.  Set ``OPENAI_API_KEY`` in the
environment and call :func:`send_prompt`.
"""

from __future__ import annotations

import json
import os
import sys
from typing import Any, Optional
from urllib.error import HTTPError, URLError
from urllib.request import Request, urlopen


API_URL = "https://api.openai.com/v1/responses"
DEFAULT_MODEL = "gpt-4.1-mini"
DEFAULT_TIMEOUT = 60.0


class OpenAIError(RuntimeError):
    """Raised when the API request cannot be completed successfully."""


def send_prompt(
    prompt: str,
    *,
    model: str = DEFAULT_MODEL,
    api_key: Optional[str] = None,
    instructions: Optional[str] = None,
    timeout: float = DEFAULT_TIMEOUT,
) -> str:
    """Send one private text prompt and return the model's text response.

    ``api_key`` defaults to ``OPENAI_API_KEY``.  Responses are sent with
    ``store=False`` so the API does not retain the response for later API use.
    This function does not log or persist the prompt, key, or response.

    Raises:
        ValueError: If an argument is invalid or the API key is missing.
        OpenAIError: If the request fails or the API returns an unusable body.
    """
    if not isinstance(prompt, str) or not prompt.strip():
        raise ValueError("prompt must be a non-empty string")
    if not isinstance(model, str) or not model.strip():
        raise ValueError("model must be a non-empty string")
    if timeout <= 0:
        raise ValueError("timeout must be greater than zero")

    key = api_key or os.environ.get("OPENAI_API_KEY")
    if not key:
        raise ValueError("set OPENAI_API_KEY or pass api_key explicitly")

    body: dict[str, Any] = {
        "model": model,
        "input": prompt,
        "store": False,
    }
    if instructions is not None:
        if not isinstance(instructions, str):
            raise ValueError("instructions must be a string or None")
        body["instructions"] = instructions

    request = Request(
        API_URL,
        data=json.dumps(body).encode("utf-8"),
        headers={
            "Authorization": f"Bearer {key}",
            "Content-Type": "application/json",
            "Accept": "application/json",
        },
        method="POST",
    )

    try:
        with urlopen(request, timeout=timeout) as response:
            raw = response.read()
    except HTTPError as exc:
        # Read only the API's error body; never include the authorization key.
        try:
            detail = json.loads(exc.read().decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError):
            detail = None
        message = _error_message(detail) or f"HTTP {exc.code} from OpenAI"
        raise OpenAIError(message) from exc
    except (URLError, TimeoutError, OSError) as exc:
        raise OpenAIError(f"could not reach OpenAI: {exc}") from exc

    try:
        data = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise OpenAIError("OpenAI returned invalid JSON") from exc

    text = _response_text(data)
    if text is None:
        raise OpenAIError("OpenAI response did not contain output text")
    return text


def _error_message(data: Any) -> Optional[str]:
    if not isinstance(data, dict):
        return None
    error = data.get("error")
    if isinstance(error, dict) and isinstance(error.get("message"), str):
        return error["message"]
    return None


def _response_text(data: Any) -> Optional[str]:
    """Extract text from a Responses API result without assuming one event type."""
    if not isinstance(data, dict):
        return None
    output_text = data.get("output_text")
    if isinstance(output_text, str):
        return output_text

    parts: list[str] = []
    output = data.get("output")
    if isinstance(output, list):
        for item in output:
            if not isinstance(item, dict) or item.get("type") != "message":
                continue
            content = item.get("content")
            if not isinstance(content, list):
                continue
            for part in content:
                if isinstance(part, dict) and part.get("type") == "output_text":
                    text = part.get("text")
                    if isinstance(text, str):
                        parts.append(text)
    return "".join(parts) if parts else None


def _main() -> int:
    import argparse

    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("prompt", nargs="?", help="text to send")
    parser.add_argument("--model", default=DEFAULT_MODEL)
    args = parser.parse_args()
    prompt = args.prompt or sys.stdin.read()
    try:
        print(send_prompt(prompt, model=args.model))
    except (ValueError, OpenAIError) as exc:
        print(f"openai_client: {exc}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(_main())
